import sys

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return
    n, t = map(int, data[0].split())
    s = list(data[1].strip())

    for _ in range(t):
        j = 0
        while j < n - 1:
            if s[j] == 'B' and s[j + 1] == 'G':
                s[j], s[j + 1] = s[j + 1], s[j]
                j += 1
            j += 1
    print(''.join(s))

if __name__ == "__main__":
    main()

